def regex_search(pattern: str, text: str) -> bool:
    p = pattern
    m = len(p)
    pos = 0

    def read_class_char() -> str:
        nonlocal pos
        c = p[pos]
        if c == '\\':
            pos += 1
            if pos >= m:
                raise ValueError("lone backslash in class")
            c = p[pos]
        pos += 1
        return c

    def parse_class() -> tuple:
        nonlocal pos
        pos += 1
        neg = False
        if pos < m and p[pos] == '^':
            neg = True
            pos += 1

        items = []
        while pos < m:
            if p[pos] == ']':
                if not items:
                    raise ValueError("empty character class")
                pos += 1
                return ('class', neg, items)

            lo = read_class_char()
            if (pos < m and p[pos] == '-' and pos + 1 < m
                    and p[pos + 1] != ']'):
                hi = read_class_char()
                if ord(lo) > ord(hi):
                    raise ValueError("invalid class range")
                items.append((lo, hi))
            else:
                items.append((lo, lo))

        raise ValueError("unclosed character class")

    def parse_element():
        nonlocal pos
        c = p[pos]

        if c == '(':
            pos += 1
            inner = parse_alternation(')')
            if pos >= m or p[pos] != ')':
                raise ValueError("unmatched (")
            pos += 1
            return ('group', inner), 'regular'

        if c == '^':
            pos += 1
            return ('assert', 1), 'anchor'

        if c == '$':
            pos += 1
            return ('assert', 2), 'anchor'

        if c == '[':
            return parse_class(), 'regular'

        if c == '.':
            pos += 1
            return ('any',), 'regular'

        if c == '\\':
            pos += 1
            if pos >= m:
                raise ValueError("lone backslash")
            ch = p[pos]
            pos += 1
            return ('char', ch), 'regular'

        pos += 1
        return ('char', c), 'regular'

    def parse_sequence(stop):
        nonlocal pos
        elements = []
        last_kind = None

        while pos < m:
            c = p[pos]
            if c == '|' or c == ')':
                break

            if c == '*' or c == '+' or c == '?':
                if last_kind != 'regular':
                    raise ValueError("invalid quantifier")
                elements[-1] = ('quant', c, elements[-1])
                last_kind = 'quant'
                pos += 1
                continue

            elem, kind = parse_element()
            elements.append(elem)
            last_kind = kind

        if not elements:
            return ('seq', [])
        if len(elements) == 1:
            return elements[0]
        return ('seq', elements)

    def parse_alternation(stop):
        nonlocal pos
        branches = []

        while True:
            branches.append(parse_sequence(stop))
            if pos >= m:
                break

            c = p[pos]
            if c == '|':
                pos += 1
                continue

            if c == ')':
                if stop == ')':
                    break
                raise ValueError("unmatched )")

            raise ValueError("unexpected character")

        if len(branches) == 1:
            return branches[0]
        return ('alt', branches)

    ast = parse_alternation(None)
    if pos != m:
        raise ValueError("invalid pattern")

    states = []

    def new_state():
        states.append([[], 0, None, -1, False])
        return len(states) - 1

    def add_eps(i, j, kind=0):
        states[i][0].append((j, kind))

    def set_match(i, kind, data, target):
        states[i][1] = kind
        states[i][2] = data
        states[i][3] = target

    def make_class_predicate(neg, items):
        ranges = [(ord(lo), ord(hi)) for lo, hi in items]

        def matches(ch: str) -> bool:
            code = ord(ch)
            for lo, hi in ranges:
                if lo <= code <= hi:
                    return not neg
            return neg

        return matches

    def compile_ast(node):
        kind = node[0]

        if kind == 'seq':
            elems = node[1]
            if not elems:
                s = new_state()
                return s, s

            start, end = compile_ast(elems[0])
            for nxt in elems[1:]:
                ns, ne = compile_ast(nxt)
                add_eps(end, ns, 0)
                end = ne
            return start, end

        if kind == 'alt':
            start = new_state()
            end = new_state()
            for branch in node[1]:
                bs, be = compile_ast(branch)
                add_eps(start, bs, 0)
                add_eps(be, end, 0)
            return start, end

        if kind == 'group':
            return compile_ast(node[1])

        if kind == 'char':
            s = new_state()
            e = new_state()
            set_match(s, 1, node[1], e)
            return s, e

        if kind == 'any':
            s = new_state()
            e = new_state()
            set_match(s, 2, None, e)
            return s, e

        if kind == 'class':
            s = new_state()
            e = new_state()
            pred = make_class_predicate(node[1], node[2])
            set_match(s, 3, pred, e)
            return s, e

        if kind == 'assert':
            s = new_state()
            e = new_state()
            add_eps(s, e, node[1])
            return s, e

        if kind == 'quant':
            op = node[1]
            inner = node[2]
            s0, e0 = compile_ast(inner)
            n0 = new_state()
            n1 = new_state()

            if op == '*':
                add_eps(n0, s0, 0)
                add_eps(n0, n1, 0)
                add_eps(e0, s0, 0)
                add_eps(e0, n1, 0)
            elif op == '+':
                add_eps(n0, s0, 0)
                add_eps(e0, s0, 0)
                add_eps(e0, n1, 0)
            else:
                add_eps(n0, s0, 0)
                add_eps(n0, n1, 0)
                add_eps(e0, n1, 0)

            return n0, n1

        raise ValueError("unknown AST node")

    start_state, final_state = compile_ast(ast)
    states[final_state][4] = True

    text_len = len(text)

    def epsilon_closure(initial_states, position):
        closed = set(initial_states)
        stack = list(closed)

        while stack:
            s = stack.pop()
            for to, guard in states[s][0]:
                if (guard == 0 or
                    (guard == 1 and position == 0) or
                    (guard == 2 and position == text_len)):
                    if to not in closed:
                        closed.add(to)
                        stack.append(to)

        return closed

    active = set()
    for at in range(text_len + 1):
        active.add(start_state)
        active = epsilon_closure(active, at)

        if final_state in active:
            return True

        if at == text_len:
            break

        ch = text[at]
        nxt = set()
        for s in active:
            match_kind = states[s][1]
            if match_kind == 1:
                if states[s][2] == ch:
                    nxt.add(states[s][3])
            elif match_kind == 2:
                nxt.add(states[s][3])
            elif match_kind == 3:
                if states[s][2](ch):
                    nxt.add(states[s][3])

        active = nxt

    return False
